INSERT INTO `mod_forever_journal_lore` (`ID`, `Zone`, `Kind`, `SortOrder`, `Faction`, `Races`, `Classes`, `Era`, `Title`, `Body`, `Sources`) VALUES
(4273000, 4273, 0, 1, 0, 0, 0, 0, 'Ulduar', 'For millennia Ulduar lay undisturbed. Since its discovery, some have thought it a city built to herald its makers'' glory, others a vault of the titans'' treasures. They were wrong. Beyond its gates lies no city, no treasure and no final answer to the titans'' mysteries: only a horror even the titans could not, or would not, destroy. They merely contained it.\n\nBeneath ancient Ulduar, the Old God of death lies whispering. It has corrupted its guards, and it is breaking through the last of its restraints.', 'warcraft.wiki.gg: Ulduar (Official Blizzard description)'),
(4273001, 4273, 1, 1, 0, 0, 0, 0, 'The Siege of Ulduar', 'The Explorers'' League and its allies have camped before the gates and brought siege engines, for the city''s defences are colossal. Its iron minions and towering war machines must be broken before anyone can set foot inside.', 'warcraft.wiki.gg: Ulduar (Official Blizzard description); warcraft.wiki.gg: Flame Leviathan'),
(4273002, 4273, 1, 2, 0, 0, 0, 0, 'The Antechamber', 'The outer works of Ulduar: the Colossal Forge, where Ignis works his furnace; the aerie where Razorscale nests; the Scrapyard of Mimiron''s mechanical son; the hall of the iron council; and the Shattered Walkway, guarded by a giant who is himself the bridge.', 'warcraft.wiki.gg: Ignis the Furnace Master; warcraft.wiki.gg: Razorscale; warcraft.wiki.gg: XT-002 Deconstructor; warcraft.wiki.gg: Assembly of Iron; warcraft.wiki.gg: Kologarn'),
(4273003, 4273, 1, 3, 0, 0, 0, 0, 'The Keepers', 'The inner halls, where the keepers of Ulduar are held captive and bent to the Old God''s will: Hodir in his frozen halls, Thorim in his arena, Freya in her conservatory of life, and Mimiron in his workshop. Free them from its grip, and they may stand with Ulduar''s challengers.', 'warcraft.wiki.gg: Hodir; warcraft.wiki.gg: Thorim; warcraft.wiki.gg: Freya; warcraft.wiki.gg: Mimiron'),
(4273004, 4273, 1, 4, 0, 0, 0, 0, 'The Descent into Madness', 'The way down to the prison itself, choked with the black saronite that is the Old God''s blood. At the bottom lies its prison, and its mind.', 'warcraft.wiki.gg: General Vezax; warcraft.wiki.gg: Yogg-Saron'),
(4273005, 4273, 1, 5, 0, 0, 0, 0, 'The Celestial Planetarium', 'Ulduar''s archive and, beyond it, a planetarium holding the stars themselves, where the titans'' watcher arrives to pass judgment.', 'warcraft.wiki.gg: Algalon the Observer'),
(4273030, 4273, 2, 1, 0, 0, 0, 0, 'Ignis the Furnace Master', 'A fire giant construct made by Loken, master of the Colossal Forge. With his brother Volkhan he enslaved the Winterskorn vrykul and forged weapons for a war against the other titan-forged.', 'warcraft.wiki.gg: Ignis the Furnace Master'),
(4273031, 4273, 2, 2, 0, 0, 0, 0, 'Razorscale', 'A proto-dragon captured by Loken and twisted into a weapon. At his orders Ignis fused iron plates onto her scales.', 'warcraft.wiki.gg: Razorscale'),
(4273032, 4273, 2, 3, 0, 0, 0, 0, 'XT-002 Deconstructor', 'A clockwork giant engineered by Mimiron, who rules the Scrapyard. He thinks of himself as the inventor''s son, and behaves like a young boy.', 'warcraft.wiki.gg: XT-002 Deconstructor'),
(4273033, 4273, 2, 4, 0, 0, 0, 0, 'The Assembly of Iron', 'The three generals of the iron armies, each of a different race: Stormcaller Brundir, Runemaster Molgeim, and Steelbreaker.', 'warcraft.wiki.gg: Assembly of Iron'),
(4273034, 4273, 2, 5, 0, 0, 0, 0, 'Kologarn', 'A towering giant Ignis made at Loken''s order to guard the Shattered Walkway into the inner sanctum, with arms massive enough to crush any intruder.', 'warcraft.wiki.gg: Kologarn'),
(4273035, 4273, 2, 6, 0, 0, 0, 0, 'Auriaya', 'A watcher who roams the Observation Ring beyond the walkway with her sanctum sentries and feral defender.', 'warcraft.wiki.gg: Auriaya'),
(4273036, 4273, 2, 7, 0, 0, 0, 0, 'Hodir', 'The keeper of winter, who once lived in the Temple of Winter and guided the frost giants of the peaks. The Sons of Hodir call him their father.', 'warcraft.wiki.gg: Hodir'),
(4273037, 4273, 2, 8, 0, 0, 0, 0, 'Thorim', 'The Stormlord, wielder of the hammer Krolmir, who led the titan-forged armies against the Old Gods'' forces. It is said his power was used only once, and turned a whole continent to dust. Loken lured him out of his temple to Ulduar, subdued him, and gave him to the Old God.', 'warcraft.wiki.gg: Thorim; warcraft.wiki.gg: Temple of Storms'),
(4273038, 4273, 2, 9, 0, 0, 0, 0, 'Freya', 'The keeper of life, who lived in the Temple of Life until Loken rebelled. The Old God took hold of her and left her dormant in Ulduar''s greenery. She left an avatar in Sholazar Basin, a safeguard for the life she made there.', 'warcraft.wiki.gg: Freya'),
(4273039, 4273, 2, 10, 0, 0, 0, 0, 'Mimiron', 'Mimir to his friends: the keeper of invention, given part of the titan Norgannon''s intellect. Loken murdered him, but his mechagnomes saved his spirit and built him a mechanical body. He has not been entirely sane since.', 'warcraft.wiki.gg: Mimiron'),
(4273040, 4273, 2, 11, 0, 0, 0, 0, 'General Vezax', 'A faceless general who guards the descent to the Old God''s prison.', 'warcraft.wiki.gg: General Vezax'),
(4273041, 4273, 2, 12, 0, 0, 0, 0, 'Yogg-Saron', 'One of the Old Gods, the beast with a thousand maws, defeated by the titans'' armies in the world''s earliest age and imprisoned in Ulduar. Trying to escape, it corrupted Loken and turned him on his brethren, and loosed the Curse of Flesh on the titans'' creations. Ages later its taint rose through the roots of the World Tree Andrassil, and the night elves had to cut it down.', 'warcraft.wiki.gg: Yogg-Saron'),
(4273042, 4273, 2, 13, 0, 0, 0, 0, 'Algalon the Observer', 'A constellar sent by the titans to watch over Azeroth, with the power to purge a corrupted world of all life and remake it. Loken''s death summoned him. He judged the world corrupted by the Old Gods and prepared to remake it, but the mortals who fought him showed such resolve that he came to doubt his judgment of them, and let them reverse the order and spare the world.', 'warcraft.wiki.gg: Algalon the Observer');
